"""t88-fix6 step1: static (dl=rec_type, r8d=tag) per 4CC handler block.
--help / --selftest per repo rules."""
import sys,json,struct,capstone
EXE='D:/tmp2b/fm24/input/editor.exe'
BASE=0x140000000
def a4(v):
    b=v.to_bytes(4,'little')
    return ''.join(chr(c) for c in b) if all(32<=c<127 for c in b) else None
def load():
    return open(EXE,'rb').read()
def blocks(d):
    md=capstone.Cs(capstone.CS_ARCH_X86,capstone.CS_MODE_64)
    lo,hi=0x11f0900,0x11f2c40
    ins=list(md.disasm(d[lo:hi],BASE+lo))
    out=[]
    pend=None
    for i in ins:
        if i.mnemonic=='mov' and i.op_str.startswith('dl, '):
            try: pend=int(i.op_str.split(', ')[1],16)
            except: pend=None
            ent=i.address-BASE
        elif i.mnemonic=='mov' and i.op_str.startswith('r8d, '):
            try: t=int(i.op_str.split(', ')[1],16)
            except: continue
            s=a4(t)
            if s: out.append({'entry':ent if pend is not None else i.address-BASE,'rec_type':pend,'tag':s,'tag_va':hex(i.address)})
        elif i.mnemonic=='jmp':
            pass
    return out
def dispatch(d):
    """code -> list of (cmp_va, je_target) for cmp esi,imm32 ascii"""
    res={}
    i=0
    while True:
        i=d.find(b'\x81\xfe',i)
        if i<0: break
        v=struct.unpack_from('<I',d,i+2)[0]; s=a4(v)
        if s:
            md=capstone.Cs(capstone.CS_ARCH_X86,capstone.CS_MODE_64)
            tgt=[]
            for k in md.disasm(d[i+6:i+6+16],BASE+i+6):
                if k.mnemonic in ('je','jne') and k.op_str.startswith('0x'):
                    tgt.append((k.mnemonic,int(k.op_str,16)-BASE))
                else: break
            res.setdefault(s,[]).append((i,tgt))
        i+=1
    return res
if __name__=='__main__':
    if '--help' in sys.argv:
        print("usage: t88_slots1.py [--selftest]  -> writes out3/_blocks.json,_dispatch2.json"); sys.exit(0)
    d=load(); bl=blocks(d); dp=dispatch(d)
    json.dump(bl,open('scratch/t88/out3/_blocks.json','w'),indent=0)
    json.dump({k:[[hex(a),[[m,hex(t)] for m,t in g]] for a,g in v] for k,v in dp.items()},open('scratch/t88/out3/_dispatch2.json','w'),indent=0)
    print('blocks',len(bl),'distinct tags',len(set(b['tag'] for b in bl)))
    print('dispatch codes',len(dp))
    ent={b['entry']:b for b in bl}
    print('block entries',len(ent))
